// 18 · Mental Health First Aid: recognizing signs without being a therapist.
// Composition: hook = one plain sentence across the slide; takeaway = big line, short rule,
// question below; alignment = left.

module.exports = {
  num: 18,
  slug: "mental-health-first-aid",
  title: "Mental Health First Aid",
  category: "Mental Health & Performance Psychology",
  palette: "paper",
  hero: { layout: "see-say-refer-path", concept: "A path that starts off the left edge and runs through three small stops (notice, ask, connect) to a larger end point: Baylor's licensed mental health staff" },
  compose: { hook: "statement", takeaway: "headline-rule-question", align: "left" },
  oneIdea: "Staff don't need to be therapists. Our part is to notice, ask and connect athletes to Baylor's licensed mental health staff; Mental Health First Aid is a course that teaches exactly that.",
  question: "Who on our staff should take the full course first?",
  caveats: `This deck is an introduction. It does not train or certify anyone in Mental Health First Aid; certification comes only from completing an MHFA course with a certified instructor. Quote the action plan (ALGEE) exactly as written on slide 4; it is the current wording on the MHFA USA site, and MHFA notes the steps can be used in any order in a non-crisis situation. Be honest about the evidence: trials show MHFA training improves knowledge, recognition, confidence and helping intentions, with small gains in the amount of help given (Morgan et al. 2018). A 2023 Cochrane review could not draw conclusions about effects on the mental health of the people being helped (very low-certainty evidence). The Gulliver study is 15 young elite athletes in focus groups: useful, not definitive. Never describe Baylor's emergency procedures from memory; point people to Baylor's licensed mental health staff and the department's emergency action plan. Safe messaging: if suicide comes up in discussion, keep the tone calm and practical, don't discuss methods, and pair it with help: in immediate danger call 911; the 988 Suicide & Crisis Lifeline (call or text 988) is free, confidential and available 24/7.`,
  sources: [
    { id: "mhfa", cite: "Mental Health First Aid USA (National Council for Mental Wellbeing). Using the 5-step MHFA Action Plan: how ALGEE helps in mental health and substance use challenges. mentalhealthfirstaid.org. Accessed October 4, 2026.", url: "https://mentalhealthfirstaid.org/news/algee-how-mhfa-helps-you-respond-in-crisis-and-non-crisis-situations/", grade: "program's own description", found: "external", supports: "The current ALGEE wording: Approach, assess for risk of suicide or harm; Listen nonjudgmentally; Give reassurance and information; Encourage appropriate professional help; Encourage self-help and other support strategies. The steps can be used in any order in a non-crisis situation." },
    { id: "morgan2018", cite: "Morgan AJ, Ross A, Reavley NJ. Systematic review and meta-analysis of Mental Health First Aid training: effects on knowledge, stigma, and helping behaviour. PLoS One. 2018;13(5):e0197102. doi:10.1371/journal.pone.0197102", grade: "systematic review and meta-analysis (18 trials)", found: "external", supports: "Small-to-moderate gains in knowledge, recognition, confidence and intentions to help up to 6 months; small gain in amount of help provided (d = 0.23); quality of help unclear." },
    { id: "richardson2023", cite: "Richardson R, Dale HE, Robertson L, et al. Mental Health First Aid as a tool for improving mental health and well-being. Cochrane Database Syst Rev. 2023;8(8):CD013127. doi:10.1002/14651858.CD013127.pub2", grade: "Cochrane systematic review", found: "external", supports: "Very low-certainty evidence; no firm conclusions possible about effects of MHFA training on the mental health of people in the communities where it is delivered." },
    { id: "gulliver2012", cite: "Gulliver A, Griffiths KM, Christensen H. Barriers and facilitators to mental health help-seeking for young elite athletes: a qualitative study. BMC Psychiatry. 2012;12:157. doi:10.1186/1471-244X-12-157", grade: "qualitative focus groups (15 athletes)", found: "external (cited in Zotero: Schnitker et al. 2020)", supports: "Stigma was the most important perceived barrier; lack of mental health literacy and negative past experiences also mattered. Facilitators included encouragement from others and the positive attitudes of others, especially the coach." },
    { id: "ncaa2024", cite: "NCAA Sport Science Institute. Mental Health Best Practices: Understanding and Supporting Student-Athlete Mental Health. 2nd ed. NCAA; 2016, revised 2020, updated 2024.", url: "https://ncaaorg.s3.amazonaws.com/ssi/mental/SSI_MentalHealthBestPractices.pdf", grade: "inter-association consensus document", found: "external", supports: "All athlete-facing staff can help identify athletes at risk (p. 6); action plans route athletes to licensed mental health providers, who perform formal evaluation and treatment (pp. 7, 9); mental health first aid is listed among suggested coach development topics (p. 5)." },
    { id: "lifeline988", cite: "988 Suicide & Crisis Lifeline. 988lifeline.org. Accessed October 4, 2026.", url: "https://988lifeline.org/", grade: "national crisis service", found: "external", supports: "Call or text 988, or chat online; free, confidential, available 24/7/365." },
  ],
  slides: [
    {
      role: "hook", time: 40,
      notes: `Most of us would know roughly what to do if an athlete collapsed on the field. Far fewer of us know what to do when an athlete just seems off: quieter than usual, missing things, not themselves.

Here's the point of the next five minutes. You don't need to be a therapist to help. You need to be the person who notices, and knows what to do next.`,
      build(s) {
        s.headline(["You don’t need to be a therapist to be ", { t: "the first one who notices.", color: "accent" }], { x: 0.75, y: 2.05, w: 11.6, h: 2.6, size: 62 });
      },
    },
    {
      role: "problem", time: 60,
      notes: `Why does this matter for us? When researchers asked young elite athletes what stops them from getting help, stigma came first: worry about what coaches and teammates will think. Not recognizing the signs, and bad experiences with help in the past, came up too.

What helped was just as clear: encouragement from people around them, and positive attitudes, especially from their coach. That was a small study, fifteen athletes in focus groups, but it lines up with the NCAA's own guidance, which says every athlete-facing staff member can help identify an athlete who is struggling.

So the people in this room are part of how athletes get to help.`,
      build(s) {
        s.headline("Stigma keeps athletes quiet. The people around them can change that.", { y: 1.2, w: 11.6, h: 1.55, size: 44 });
        s.label("What holds them back", { x: 0.75, y: 3.3, w: 5.2 });
        s.text(0.75, 3.75, 5.35, 2.0, "Stigma first. Then not knowing the signs, and bad past experiences.", { font: "light", size: 24, lineH: 1.2 });
        s.label("What helps", { x: 7.1, y: 3.3, w: 5.2, color: "accent" });
        s.text(7.1, 3.75, 5.45, 2.0, "Encouragement from others, and a coach with a positive attitude.", { font: "light", size: 24, lineH: 1.2 });
        s.source("Gulliver, Griffiths & Christensen 2012 (focus groups, 15 young elite athletes) · NCAA Mental Health Best Practices 2024", { y: 6.0, w: 11.8, size: 12, refs: ["gulliver2012", "ncaa2024"] });
      },
    },
    {
      role: "insight", time: 75,
      notes: `So what is our part? Three steps. Notice: a change from the athlete's usual self. Ask: privately, directly, and then listen more than you talk. Connect: help them get to Baylor's licensed mental health staff, and offer to go with them.

Everything after that, the assessment, the diagnosis, the treatment, belongs to licensed clinicians. That's what the NCAA's best practices call for, and it takes pressure off the rest of us.

One honest note on the training. Studies show Mental Health First Aid courses reliably build people's knowledge and confidence to help. Whether that improves the mental health of the people they help hasn't been shown yet. It's a good start, not a guarantee.`,
      build(s) {
        s.headline("Our part is the first three steps. Care belongs to the clinicians.", { y: 1.2, w: 10.5, h: 1.25, size: 40 });
        const y = 3.85;
        const stops = [[2.3, "Notice"], [4.9, "Ask"], [7.5, "Connect"]];
        s.line(0, y, 9.55, y, { color: "muted", w: 1.5 });
        stops.forEach(([x, t]) => {
          s.circle(x, y, 0.13, { fill: "ink" });
          s.text(x - 1.0, y + 0.3, 2.0, 0.5, t, { font: "cond", size: 24, color: "ink", align: "center" });
        });
        s.line(7.5, y, 9.55, y, { color: "accent", w: 3, arrow: "end" });
        s.circle(10.45, y, 0.75, { line: "accent", lineW: 2.5 });
        s.text(9.55, y + 0.9, 3.03, 0.85, "Baylor’s licensed mental health staff", { font: "condBold", size: 20, color: "accent", align: "center", lineH: 1.05 });
        s.text(0.75, 5.35, 8.3, 0.75, "Training builds helpers’ knowledge and confidence. Its effect on the people helped is still unproven.", { font: "light", size: 18, color: "muted", lineH: 1.2 });
        s.source("Referral to licensed providers: NCAA 2024 · Training effects: Morgan et al. 2018; Cochrane review, Richardson et al. 2023", { y: 6.2, w: 11.8, refs: ["ncaa2024", "morgan2018", "richardson2023"] });
      },
    },
    {
      role: "application", time: 65,
