// 19 · Athlete Identity & Life Balance: the risk of single-identity investment.
// Composition: hook = small figure bottom-right in a large empty field, one-line headline
// top-left; takeaway = line | question split by a vertical rule; alignment = right.

module.exports = {
  num: 19,
  slug: "athlete-identity-and-life-balance",
  title: "Athlete Identity & Life Balance",
  category: "Mental Health & Performance Psychology",
  palette: "gold",
  hero: { layout: "two-ring-comparison", concept: "Two rings hugging the right margin: one almost entirely 'athlete', one where athlete is the biggest part of a broader mix (student, friend and family, faith and interests)" },
  compose: { hook: "small-figure-field", takeaway: "split-columns", align: "right" },
  oneIdea: "A strong athletic identity isn't the problem; an exclusive one is. Staff can help athletes build the rest of who they are while they are still playing.",
  question: "What do we know about our athletes beyond their sport?",
  caveats: `Don't frame a strong athletic identity as bad. Commitment to sport is part of why athletes succeed; the risk in the research is an identity that is exclusive (foreclosed) or a sense of worth that rides on performance. The Houltberg study is one survey of 99 elite athletes at a single point in time: performance-based identity went with more depression, anxiety and shame, but the design can't show cause. The two rings on slide 3 are illustrative, not data. The 1.4% figure is the NCAA's estimate for football only: 2025 NFL draft picks divided by draft-eligible NCAA players; it excludes other professional leagues, and other sports differ (the NCAA's estimates for men's and women's basketball and baseball range from about 1% to 5%). Use it to make the point that every playing career ends, not to discourage anyone. If an athlete seems to be struggling after an injury, a loss of playing time or the end of a career, connect them with Baylor's licensed mental health staff.`,
  sources: [
    { id: "ncaa2025", cite: "NCAA Research. Probability of competing beyond high school: estimated probability of competing in professional athletics (2025 NFL draft). NCAA.org. Accessed October 4, 2026.", url: "https://www.ncaa.org/student-athletes/probability-of-competing-beyond-high-school/", grade: "NCAA research estimate", found: "external", supports: "Football: 257 NFL draft picks from about 18,621 draft-eligible NCAA players in 2025, 1.4%." },
    { id: "houltberg2018", cite: "Houltberg BJ, Wang KT, Qi W, Nelson CS. Self-narrative profiles of elite athletes and comparisons on psychological well-being. Res Q Exerc Sport. 2018;89(3):354-360. doi:10.1080/02701367.2018.1481919", grade: "cross-sectional survey (n = 99 NCAA Division I, professional and Olympic athletes)", found: "Zotero", supports: "Athletes with a performance-based narrative identity (perfectionism, fear of failure, contingent self-worth) reported the highest depression, anxiety and shame; a purpose-based identity went with the lowest levels and the highest life satisfaction. Cross-sectional, so causality can't be determined (p. 7)." },
    { id: "houltberg2020", cite: "Houltberg BJ, Scholefield RM. Developmental model of elite athletes: the integration of developmental science and practitioner experience. Prof Psychol Res Pr. 2020;51(6):550-559. doi:10.1037/pro0000316", grade: "practitioner model / narrative review", found: "Zotero", supports: "The time commitment of elite sport may require a foreclosure around the athlete identity that limits identity exploration; the athlete identity becomes stronger and more central to self-concept (p. 5)." },
    { id: "murphy1996", cite: "Murphy GM, Petitpas AJ, Brewer BW. Identity foreclosure, athletic identity, and career maturity in intercollegiate athletes. Sport Psychol. 1996;10(3):239-246. doi:10.1123/tsp.10.3.239", grade: "cross-sectional study, college athletes", found: "external (cited in Zotero: Houltberg & Scholefield 2020)", supports: "Identity foreclosure and strong athletic identity were associated with lower career maturity in intercollegiate athletes." },
    { id: "park2013", cite: "Park S, Lavallee D, Tod D. Athletes' career transition out of sport: a systematic review. Int Rev Sport Exerc Psychol. 2013;6(1):22-53. doi:10.1080/1750984X.2012.687053", grade: "systematic review", found: "external", supports: "Athletic identity is widely reported as a key factor in how well athletes adjust when they leave sport; proactive support is a suggested practical implication." },
  ],
  slides: [
    {
      role: "hook", time: 45,
      notes: `Here's a number most of our athletes know and few like to think about. In the 2025 NFL draft, the NCAA estimates about 1.4 percent of draft-eligible college football players were picked. Other sports differ, but the shape is the same everywhere.

The point isn't to discourage anyone. It's that every playing career ends, for most of our athletes at graduation, for some earlier through injury. So the question for us is what's left of who they are when it does.`,
      build(s) {
        s.headline("Every playing career ends.", { y: 1.25, w: 8, h: 0.9, size: 48 });
        s.figure("1.4%", { x: 6.58, y: 3.35, w: 6.0, h: 1.95, size: 120, align: "right", refs: ["ncaa2025"] });
        s.text(6.08, 5.3, 6.5, 0.75, "of draft-eligible NCAA football players were drafted in 2025", { font: "light", size: 20, color: "muted", align: "right", lineH: 1.15 });
        s.source("NCAA Research, estimated probability of competing professionally", { x: 4.58, y: 6.15, w: 8.0, align: "right", refs: ["ncaa2025"] });
      },
    },
    {
      role: "problem", time: 60,
      notes: `Here's why that matters for wellbeing, not just careers. Elite sport takes so much time that many athletes never get to explore who else they are. Researchers call it identity foreclosure, and in college athletes it goes with less readiness for life after sport.

There's a second piece. In a survey of elite athletes, including Division I, the ones whose sense of worth rode on performance, perfectionism and fear of failure, reported the most depression, anxiety and shame. The ones with a sense of purpose reported the least. That's one study at one point in time, so it shows a link, not a cause. But it matches what many of us see after a bad game.`,
      build(s) {
        s.headline("When worth rides on performance, a bad game hurts more.", { x: 3.58, y: 1.2, w: 9.0, h: 1.55, size: 44, align: "right" });
        s.text(4.58, 3.3, 8.0, 2.2, "Athletes whose sense of worth hinged on results reported the most depression, anxiety and shame. Those with a sense of purpose reported the least.", { font: "light", size: 26, lineH: 1.2, align: "right" });
        s.source("Houltberg et al. 2018: one survey of 99 elite athletes, a link, not a cause · Murphy et al. 1996", { x: 2.58, y: 6.0, w: 10.0, size: 12, align: "right", refs: ["houltberg2018", "murphy1996", "houltberg2020"] });
      },
    },
    {
      role: "insight", time: 70,
      notes: `So here's the distinction that matters. A strong athletic identity is fine. It's part of why our athletes are good. The risk is when it's the only one.

Look at the two rings. They're illustrative, not measured. On the left, almost everything is "athlete". On the right, athlete is still the biggest piece, but there's also student, friends and family, faith, other interests.

When sport goes away, or just goes badly, the athlete on the right still has most of who they are. Research on athletes leaving sport keeps pointing to identity as one of the main factors in how well they adjust.`,
      build(s) {
        s.headline("Strong is fine. Only is the risk.", { x: 3.58, y: 1.2, w: 9.0, h: 1.0, size: 56, align: "right" });
        s.lead("A big athletic identity isn’t the problem. Having nothing else is.", { x: 5.08, y: 2.4, w: 7.5, h: 0.8, size: 22, align: "right" });
        const r = 0.92, cy = 4.65, t = 0.2;
        const ringA = 7.85, ringB = 11.66;
        // Ring A: almost all athlete.
        s.arc(ringA, cy, r, 0, 338, { thick: t, color: "accent" });
        s.arc(ringA, cy, r, 344, 356, { thick: t, color: "muted" });
        // Ring B: athlete is the largest part of a broader mix.
        s.arc(ringB, cy, r, 0, 160, { thick: t, color: "accent" });
        s.arc(ringB, cy, r, 166, 236, { thick: t, color: "muted" });
        s.arc(ringB, cy, r, 242, 298, { thick: t, color: "muted" });
        s.arc(ringB, cy, r, 304, 354, { thick: t, color: "muted" });
        s.text(ringA - 1.4, cy + r + 0.15, 2.8, 0.45, "Only athlete", { font: "cond", size: 20, color: "ink", align: "center" });
        s.text(ringB - 1.6, cy + r + 0.15, 2.52 + 0.68, 0.45, "Athlete, and more", { font: "cond", size: 20, color: "ink", align: "center" });
        s.text(0.75, cy - 0.65, 5.2, 1.4, "Student\nFriends and family\nFaith, other interests", { font: "light", size: 18, color: "muted", lineH: 1.25 });
        s.line(4.2, cy - 0.05, ringB - r - 0.25 - 3.0, cy - 0.05, { color: "rule", w: 0 });
        s.source("Illustrative, not data · Park, Lavallee & Tod 2013 · Houltberg et al. 2018", { x: 4.58, y: 6.2, w: 8.0, align: "right", refs: ["park2013", "houltberg2018"] });
      },
    },
    {
      role: "application", time: 60,
      notes: `What can we do? Two moments matter most.

When an athlete has had a loss or a bad performance, talk about something besides the result, at least some of the time. It tells them their worth isn't the box score.

When there's an injury, or it's the last season, start the next-chapter conversation early, and bring in the people who do this for a living: academics and student-athlete development. The research on career transitions keeps recommending support before the end, not after.

And if an athlete seems to be really struggling through either of these, that's a handoff to Baylor's licensed mental health staff.`,
      build(s) {
        s.headline("Build the rest of who they are while they still play.", { x: 2.58, y: 1.2, w: 10.0, h: 1.5, size: 44, align: "right" });
        const rows = [
          ["After a loss or a bad game", "Talk about something besides the result."],
          ["Injury, or the last season", "Start the next-chapter talk early, with academics and student-athlete development."],
        ];
        s.label("When", { x: 0.75, y: 3.0, w: 3 });
        s.label("Do", { x: 5.0, y: 3.0, w: 3 });
        rows.forEach(([w, d], i) => {
          const y = 3.45 + i * 1.3;
          s.line(0.75, y, 12.58, y, { color: "rule", w: 1 });
          s.text(0.75, y + 0.22, 4.0, 0.95, w, { font: "cond", size: 24, color: "ink", lineH: 1.1 });
          s.text(5.0, y + 0.2, 7.58, 1.0, d, { font: "light", size: 24, color: "ink", lineH: 1.18 });
        });
        s.line(0.75, 6.05, 12.58, 6.05, { color: "rule", w: 1 });
        s.cite("park2013");
      },
    },
    {
      role: "takeaway", time: 50,
      notes: `The takeaway: ask about the person, not just the player. It costs nothing and it's one of the few things that protects an athlete for the day sport ends.

Question for the room: what do we know about our athletes beyond their sport? Their major, what they want to do next, what they care about outside the building. If the honest answer is "not much", that's useful to know, and it's the easiest thing on this list to change.`,
      build(s) {
        s.headline("Ask about the person, not just the player.", { x: 0.75, y: 1.7, w: 5.7, h: 3.2, size: 60 });
        s.line(6.9, 1.8, 6.9, 5.9, { color: "rule", w: 1 });
        s.text(7.45, 1.8, 5.13, 2.4, "What do we know about our athletes beyond their sport?", { font: "medium", size: 32, color: "accent", lineH: 1.15, align: "right" });
      },
    },
  ],
};

